/// Builds the isolated Administration status sub-router.
pub fn administration_routes(state: AdministrationApiState) -> Router {
    Router::new()
        .route("/administration", get(administration_page))
        .route(
            "/api/v1/repositories/:repository_id/administration/status",
            get(repository_administration_status),
        )
        .route(
            "/api/v1/administration/policies",
            post(policy::adopt_administration_policy),
        )
        .route(
            "/api/v1/administration/snapshots",
            post(snapshot::request_platform_snapshot),
        )
        .route(
            "/api/v1/administration/snapshots/:request_id",
            get(snapshot::platform_snapshot_receipt),
        )
        .route(
            "/api/v1/repositories/:repository_id/administration/purges",
            post(purge::preview_lifecycle_purge),
        )
        .route(
            "/api/v1/repositories/:repository_id/administration/purges/:request_id/confirm",
            post(purge::confirm_lifecycle_purge),
        )
        .route(
            "/api/v1/repositories/:repository_id/administration/purges/:request_id",
            get(purge::lifecycle_purge_status),
        )
        .route(
            "/api/v1/administration/snapshots/:request_id/inspect",
            post(recovery::inspect_snapshot).get(recovery::latest_snapshot_inspection),
        )
        .route(
            "/api/v1/administration/recovery-executions",
            post(recovery_execution::preview_recovery_execution),
        )
        .route(
            "/api/v1/administration/recovery-executions/:request_id/confirm",
            post(recovery_execution::confirm_recovery_execution),
        )
        .route(
            "/api/v1/administration/recovery-executions/:request_id/execute",
            post(recovery_execution::execute_recovery_execution),
        )
        .route(
            "/api/v1/administration/recovery-executions/:request_id",
            get(recovery_execution::recovery_execution_status),
        )
        .route(
            "/api/v1/repositories/:repository_id/administration/exports",
            post(export::request_export),
        )
        .route(
            "/api/v1/repositories/:repository_id/administration/exports/:request_id",
            get(export::export_receipt),
        )
        .with_state(state)
}

