#[derive(Serialize)]
struct AdministrationStatusResponse {
    repository_id: String,
    projection: ProjectionStatus,
    durability: DurabilityStatus,
    capabilities: Vec<AdministrationCapability>,
}

#[derive(Serialize)]
struct ProjectionStatus {
    freshness: &'static str,
    ledger_stream_position: i64,
    projection_stream_position: Option<i64>,
    projection_updated_at_seconds: Option<u64>,
}

#[derive(Serialize)]
struct DurabilityStatus {
    state: &'static str,
    reason: &'static str,
}

#[derive(Debug, PartialEq, Eq, Serialize)]
struct AdministrationCapability {
    operation: &'static str,
    state: &'static str,
    reason: String,
}

async fn administration_page() -> Html<&'static str> {
    Html(ADMINISTRATION_PAGE)
}

async fn repository_administration_status(
    State(state): State<AdministrationApiState>,
    Path(repository_id): Path<String>,
) -> Result<Json<AdministrationStatusResponse>, StatusCode> {
    let detail = state
        .fleet
        .repository(state.tenant_id.as_ref(), &repository_id)
        .await
        .map_err(|error| {
            tracing::error!(%error, "Bridge Administration repository status query failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?
        .ok_or(StatusCode::NOT_FOUND)?;

    Ok(Json(AdministrationStatusResponse {
        repository_id: detail.repository_id,
        projection: ProjectionStatus {
            freshness: freshness_label(detail.freshness),
            ledger_stream_position: detail.ledger_stream_position,
            projection_stream_position: detail.projection_stream_position,
            projection_updated_at_seconds: unix_seconds(detail.projection_updated_at),
        },
        // The server's `DurabilityProfile` is process-local today. The Bridge
        // must not infer a durable claim from a missing published record.
        durability: DurabilityStatus {
            state: "not_reported",
            reason: "The deployment has not published a tenant-scoped durability report.",
        },
        capabilities: capabilities(&state).await,
    }))
}

async fn capabilities(state: &AdministrationApiState) -> Vec<AdministrationCapability> {
    let snapshot = match &state.snapshot {
        None => AdministrationCapability {
            operation: "snapshot",
            state: "unavailable",
            reason: "ACKPLANE_SNAPSHOT_DIR is not configured for this deployment.".to_string(),
        },
        Some(_) => {
            let administration = &state.administration;
            let active = administration
                .active_policy(
                    AdministrationOperation::Snapshot,
                    &AdministrationScope::Platform,
                    SystemTime::now(),
                )
                .await;
            match active {
                Ok(Some(_)) => AdministrationCapability {
                    operation: "snapshot",
                    state: "available",
                    reason: "A verified principal (ADR-0128) and an adopted platform policy authorize a Snapshot.".to_string(),
                },
                Ok(None) => AdministrationCapability {
                    operation: "snapshot",
                    state: "refused",
                    reason: "No adopted policy authorizes a platform Snapshot yet; adopt one via POST /api/v1/administration/policies (ADR-0119 decision 2).".to_string(),
                },
                Err(error) => {
                    tracing::error!(%error, "Bridge Administration policy lookup failed");
                    AdministrationCapability {
                        operation: "snapshot",
                        state: "unavailable",
                        reason: "The adopted-policy store could not be read.".to_string(),
                    }
                }
            }
        }
    };
    let lifecycle_purge = {
        let administration = &state.administration;
        let active = administration
            .active_policy(
                AdministrationOperation::LifecyclePurge,
                &AdministrationScope::Tenant(state.tenant_id.to_string()),
                SystemTime::now(),
            )
            .await;
        match active {
            Ok(Some(_)) => AdministrationCapability {
                operation: "lifecycle_purge",
                state: "available",
                reason: "A verified principal (ADR-0128) and an adopted tenant policy authorize a preview; confirmation still needs its own unexpired window (ADR-0119 decision 9).".to_string(),
            },
            Ok(None) => AdministrationCapability {
                operation: "lifecycle_purge",
                state: "refused",
                reason: "No adopted policy authorizes a Lifecycle purge yet; adopt one via POST /api/v1/administration/policies (ADR-0119 decision 2).".to_string(),
            },
            Err(error) => {
                tracing::error!(%error, "Bridge Administration policy lookup failed");
                AdministrationCapability {
                    operation: "lifecycle_purge",
                    state: "unavailable",
                    reason: "The adopted-policy store could not be read.".to_string(),
                }
            }
        }
    };
    let export = match &state.export {
        None => AdministrationCapability {
            operation: "export",
            state: "unavailable",
            reason: "ACKPLANE_EXPORT_DIR is not configured for this deployment.".to_string(),
        },
        Some(_) => {
            let administration = &state.administration;
            let active = administration
                .active_policy(
                    AdministrationOperation::Export,
                    &AdministrationScope::Tenant(state.tenant_id.to_string()),
                    SystemTime::now(),
                )
                .await;
            match active {
                Ok(Some(_)) => AdministrationCapability {
                    operation: "export",
                    state: "available",
                    reason: "A verified principal (ADR-0128) and an adopted tenant policy authorize a bounded, redacted Export.".to_string(),
                },
                Ok(None) => AdministrationCapability {
                    operation: "export",
                    state: "refused",
                    reason: "No adopted policy authorizes an Export yet; adopt one via POST /api/v1/administration/policies (ADR-0119 decision 2).".to_string(),
                },
                Err(error) => {
                    tracing::error!(%error, "Bridge Administration policy lookup failed");
                    AdministrationCapability {
                        operation: "export",
                        state: "unavailable",
                        reason: "The adopted-policy store could not be read.".to_string(),
                    }
                }
            }
        }
    };
    vec![
        AdministrationCapability {
            operation: "status_inspection",
            state: "available",
            reason: "Tenant-scoped projection and capability status are readable.".to_string(),
        },
        snapshot,
        export,
        AdministrationCapability {
            operation: "claim_recovery",
            state: "available",
            reason: "Only an expired claim can be recovered; the next owner and a reason are recorded, and live claims refuse.".to_string(),
        },
        AdministrationCapability {
            operation: "recovery_inspection",
            state: if state.snapshot.is_some() {
                "available"
            } else {
                "unavailable"
            },
            reason: if state.snapshot.is_some() {
                "Inspects one identified Snapshot's artifact (integrity, decryption, archive validity); no adopted policy is required (ADR-0119 decision 2 does not list inspection as privileged). Refuses per-request if that Snapshot has no succeeded receipt to inspect.".to_string()
            } else {
                "ACKPLANE_SNAPSHOT_DIR is not configured for this deployment, so no Snapshot artifact can exist to inspect.".to_string()
            },
        },
        lifecycle_purge,
    ]
}

fn administration_error_status(error: AdministrationStoreError) -> StatusCode {
    match error {
        AdministrationStoreError::NoActivePolicy
        | AdministrationStoreError::PolicyIdempotencyConflict
        | AdministrationStoreError::RequestIdempotencyConflict
        | AdministrationStoreError::ReceiptConflict => StatusCode::CONFLICT,
        AdministrationStoreError::InvalidIdentifier { .. }
        | AdministrationStoreError::InvalidDataClassification
        | AdministrationStoreError::InvalidRetentionBasis
        | AdministrationStoreError::InvalidPolicyLifetime
        | AdministrationStoreError::InvalidReason
        | AdministrationStoreError::InvalidArtifactPath
        | AdministrationStoreError::InvalidManifestDigest
        | AdministrationStoreError::InvalidReceiptTime
        | AdministrationStoreError::InvalidTimestamp
        | AdministrationStoreError::InvalidConfirmationWindow
        | AdministrationStoreError::InvalidPurpose
        | AdministrationStoreError::InvalidMaxRecords
        | AdministrationStoreError::InvalidSchemaVersion
        | AdministrationStoreError::InconsistentScope
        | AdministrationStoreError::IncompleteConfirmationPrincipal => StatusCode::BAD_REQUEST,
        AdministrationStoreError::SelfConfirmationRefused => StatusCode::FORBIDDEN,
        AdministrationStoreError::LegacyPurgeRequestUnauthenticated => StatusCode::CONFLICT,
        AdministrationStoreError::UnknownPolicy { .. }
        | AdministrationStoreError::UnknownRequest { .. }
        | AdministrationStoreError::UnknownPurgeRequest { .. }
        | AdministrationStoreError::UnknownExportRequest { .. }
        | AdministrationStoreError::UnknownRecoveryExecutionRequest { .. } => StatusCode::NOT_FOUND,
        AdministrationStoreError::UnknownRecoveryArtifact
        | AdministrationStoreError::RecoveryArtifactManifestMismatch
        | AdministrationStoreError::RecoveryExecutionNotConfirmed
        | AdministrationStoreError::NoPassingRehearsalForArtifact => StatusCode::CONFLICT,
        error @ (AdministrationStoreError::Database(_)
        | AdministrationStoreError::UnknownOperation { .. }
        | AdministrationStoreError::UnknownOutcome { .. }
        | AdministrationStoreError::UnknownDataCategory { .. }) => {
            tracing::error!(%error, "Bridge Administration store error");
            StatusCode::INTERNAL_SERVER_ERROR
        }
        error @ AdministrationStoreError::PoolExhausted(_) => {
            tracing::error!(%error, "Bridge Administration store connection pool exhausted");
            StatusCode::SERVICE_UNAVAILABLE
        }
    }
}

fn freshness_label(freshness: RepositoryFreshness) -> &'static str {
    match freshness {
        RepositoryFreshness::NeverProjected => "never_projected",
        RepositoryFreshness::Lagging => "lagging",
        RepositoryFreshness::Fresh => "fresh",
    }
}

fn unix_seconds(timestamp: Option<SystemTime>) -> Option<u64> {
    timestamp.and_then(|timestamp| {
        timestamp
            .duration_since(UNIX_EPOCH)
            .ok()
            .map(|duration| duration.as_secs())
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn administration_page_hosts_a_status_only_contract() {
        assert_eq!(administration_page().await.0, ADMINISTRATION_PAGE);
        assert!(ADMINISTRATION_PAGE.contains("Administration status"));
        assert!(ADMINISTRATION_PAGE.contains("status.durability.state"));
        assert!(!ADMINISTRATION_PAGE.contains("DROP DATABASE"));
        assert!(!ADMINISTRATION_PAGE.contains("TRUNCATE"));
        assert!(!ADMINISTRATION_PAGE.contains("database credentials"));
    }
}
